--####################
--## #####RULES #######
--####################

hl.window_rule({
    name = "suppress-maximize-events",
    match = {
        class = ".*",
    },
    -- Ignore maximize requests from all apps. You'll probably like this.
    suppress_event = "maximize",
})

hl.window_rule({
    name = "fix-xwayland-drags",
    match = {
        class = "^$",
        title = "^$",
        xwayland = true,
        float = true,
        fullscreen = false,
        pin = true,
    },
    -- Fix some dragging issues with XWayland
    no_focus = true,
})

hl.window_rule({
    name = "move-hyprland-run",
    match = {
        class = "hyprland-run",
    },
    move = "20 monitor_h-120",
    float = true,
})

hl.window_rule({
    name = "wofi-style",
    match = {
        class = "wofi",
    },
    -- Aplica la opacidad (90% activa, 80% inactiva)
    opacity = "0.9 0.8",
    -- Forzar que flote para que Hyprland no lo rompa
    float = true,
})

hl.window_rule({
    name = "thunar",
    match = {
        class = "thunar",
    },
    -- Opacidad: 92% cuando lo usas, 85% cuando estás en otra ventana
    opacity = "1.90 1.00",
})

